select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_HU_REPACK_CMD','RRL_STOCK_HU_CMD','RRL_STOCK_HU_SLOT','RRL_STOCK_HU_PLACEMENT_CORE','RRL_STOCK_RESERVE_CORE','RRL_STOCK_POSTING_API');
